"""Observability for one gated barge-in decision."""

from __future__ import annotations

from contextlib import contextmanager
from typing import Iterator, Optional

from opentelemetry.trace import Span

from rasa.tracing.voice.metrics import (
    InteractionOutcome,
    record_barge_in_decision_metric,
)
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import (
    content_capture_enabled,
    voice_stage_span,
)


class BargeInDecisionRecorder:
    """Record one gated barge-in classification as span events and a metric.

    Each verdict counts one barge-in decision tagged with the outcome and
    the detector's reason. Span writes are skipped when the wrapped span
    is non-recording (tracing disabled).
    """

    def __init__(self, span: Span) -> None:
        self.span = span

    def record_accepted(
        self,
        *,
        reason: Optional[str],
        transcript: str,
        audio_was_active: Optional[bool] = None,
    ) -> None:
        """Record an accepted barge-in verdict.

        Args:
            reason: Detector's reason for the verdict.
            transcript: Classified transcript, subject to content capture.
            audio_was_active: Whether agent audio was buffered or playing when the
                transcript arrived.
        """
        record_barge_in_decision_metric(
            outcome=InteractionOutcome.ACCEPTED, reason=reason
        )
        self._record_verdict(
            semconv.EVENT_BARGE_IN_ACCEPTED,
            reason=reason,
            transcript=transcript,
            audio_was_active=audio_was_active,
        )

    def record_ignored(
        self,
        *,
        reason: Optional[str],
        transcript: str,
        audio_was_active: Optional[bool] = None,
    ) -> None:
        """Record an ignored barge-in verdict.

        Args:
            reason: Detector's reason for the verdict.
            transcript: Classified transcript, subject to content capture (content
                capture is enabled by RASA_VOICE_CAPTURE_CONTENT).
            audio_was_active: Whether agent audio was buffered or playing when the
                transcript arrived.
        """
        record_barge_in_decision_metric(
            outcome=InteractionOutcome.IGNORED, reason=reason
        )
        self._record_verdict(
            semconv.EVENT_BARGE_IN_IGNORED,
            reason=reason,
            transcript=transcript,
            audio_was_active=audio_was_active,
        )

    def _record_verdict(
        self,
        name: str,
        *,
        reason: Optional[str],
        transcript: str,
        audio_was_active: Optional[bool] = None,
    ) -> None:
        if not self.span.is_recording():
            return

        attributes: dict[str, object] = {}
        if reason is not None:
            attributes[semconv.VOICE_BARGE_IN_REASON] = reason
        if audio_was_active is not None:
            attributes[semconv.VOICE_BARGE_IN_AUDIO_WAS_ACTIVE] = audio_was_active
        if content_capture_enabled():
            attributes[semconv.VOICE_BARGE_IN_TRANSCRIPT] = transcript
        self.span.add_event(name, attributes)


@contextmanager
def handle_barge_in_span(*, transcript: str) -> Iterator[BargeInDecisionRecorder]:
    """Open a `handle barge-in` span around one gated barge-in decision.

    Opened only after the handler's gates pass (agent speaking, interruptions
    allowed) — skipped transcripts never create a span. A crashing decision
    records ``voice.barge_in_failed``, and the underlying stage span records the
    exception and ERROR status before re-raising.

    Args:
        transcript: The transcript that triggered the decision. Stamped on the
            ``voice.barge_in_attempted`` event only when content capture is
            enabled (``RASA_VOICE_CAPTURE_CONTENT``).

    Yields:
        The decision recorder. Span writes are no-ops without tracing; metrics
        remain active when configured.
    """
    with voice_stage_span(semconv.SPAN_NAME_HANDLE_BARGE_IN) as span:
        barge_in_span = BargeInDecisionRecorder(span)
        if span.is_recording():
            attempted_attributes = {}
            if content_capture_enabled():
                attempted_attributes[semconv.VOICE_BARGE_IN_TRANSCRIPT] = transcript
            span.add_event(semconv.EVENT_BARGE_IN_ATTEMPTED, attempted_attributes)
        try:
            yield barge_in_span
        except Exception:
            if span.is_recording():
                span.add_event(semconv.EVENT_BARGE_IN_FAILED)
            raise
